def count_digits_letters(string):
    # Initializing counters
    digits = 0
    letters = 0
    # Checking each character
    for char in string:
        if char.isdigit():
            digits += 1
        elif char.isalpha():
            letters += 1
    # Returning the counts
    return digits, letters

