def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_divisor = int(n ** 0.5) + 1
    for d in range(3, max_divisor, 2):
        if n % d == 0:
            return False
    return True

def first_primes(n):
    primes = []
    possible_prime = 2
    while len(primes) < n:
        if is_prime(possible_prime):
            primes.append(possible_prime)
        possible_prime += 1
    return primes

