def factorial(n):
    """
    Function to calculate the factorial of a number.
    Factorials are calculated by multiplying a series of descending positive integers
    """
    if n == 0:
        return 1
    else:
        fact = 1
        for i in range(1, n + 1):
            fact *= i
        return fact

